INSERT INTO [__mj].[Query] ([ID], [Name], [UserQuestion], [Description], [SQL], [Status], [Reusable], [CacheEnabled], [AuditQueryRuns], [UsesTemplate])
VALUES
  ('7A8CE96D-F836-5FD1-923A-FD00D3980B26', N'Members by segment and region', N'How are our members distributed across segments and regions?', N'Member profile counts grouped by segment and region.', N'SELECT Segment, Region, COUNT(*) AS Members FROM [morecheese_members].[vwMemberProfiles] GROUP BY Segment, Region ORDER BY Members DESC', N'Approved', 1, 0, 0, 0),
  ('ADF3538E-B0A7-5B36-8F6A-2B291F47EB55', N'Open issues by type and severity', N'What support issues are open right now, and how severe are they?', N'Open ticket counts by issue type and severity.', N'SELECT IssueType, Severity, COUNT(*) AS OpenIssues FROM [__mj_BizAppsIssues].[vwIssues] WHERE Status NOT IN (''Resolved'',''Closed'') GROUP BY IssueType, Severity ORDER BY OpenIssues DESC', N'Approved', 1, 0, 0, 0),
  ('B5879510-E733-53C4-BC4B-E27F34A0ECBB', N'Lapsed memberships by year', N'How many memberships lapsed each year?', N'Lapse counts by the year the membership period ended.', N'SELECT YEAR(EndDate) AS YearEnded, COUNT(*) AS Lapsed FROM [morecheese_members].[vwMembershipPeriods] WHERE Status=''Lapsed'' GROUP BY YEAR(EndDate) ORDER BY YearEnded', N'Approved', 1, 0, 0, 0);
